exercises.solution_code:
def es_primo(numero):
    if numero < 2:
        return False
    for divisor in range(2, numero):
        if numero % divisor == 0:
            return False
    return True

numero = int(input())
if es_primo(numero):
    print("Primo")
else:
    print("No primo")

